<?php
require_once 'includes/functions.php'; require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$n=trim($_POST['test_name']??'');$c=(int)($_POST['category_id']??0);$p=(float)($_POST['price']??0);$d=trim($_POST['description']??'');if($n&&$c&&$p>=0){db()->prepare('INSERT INTO laboratory_tests(category_id,test_name,price,description) VALUES(?,?,?,?)')->execute([$c,$n,$p,$d]);flash('Laboratory test added.');}else flash('Please enter valid test details.','error');redirect('tests.php');}
header_html('Laboratory tests');$cats=db()->query('SELECT * FROM test_categories ORDER BY name')->fetchAll();$rows=db()->query('SELECT t.*,c.name category FROM laboratory_tests t JOIN test_categories c ON c.id=t.category_id ORDER BY t.id DESC')->fetchAll();?>
<h1>Laboratory tests</h1><section class="card"><form method="post"><?=csrf_field()?><label>Test name</label><input name="test_name" required><label>Category</label><select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><label>Price (₹)</label><input type="number" name="price" min="0" step="0.01" value="0"><label>Description</label><textarea name="description"></textarea><button>Add test</button></form></section>
<section class="card"><h2>Test catalogue</h2><table><tr><th>Test</th><th>Category</th><th>Price</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['test_name'])?></td><td><?=e($r['category'])?></td><td>₹<?=e($r['price'])?></td></tr><?php endforeach;?></table></section><?php footer_html();?>
